from pathlib import Path

p = Path('app.py')
text = p.read_text()

import_anchor = 'from persistent_actions import render_action_manager\n'
import_block = '''from persistent_actions import render_action_manager\nfrom drive_storage import (\n    download_source_file,\n    latest_source_file,\n    save_source_file,\n    source_storage_configured,\n    source_storage_status,\n)\n'''
